/**
 * Test flow for SLA Task trigger - Advanced Workflow
 * Tests: Real-world SLA monitoring with percentage timers and notifications
 *
 * Workflow:
 * 1. Wait for 25% of SLA completion
 * 2. Send notification at 25%
 * 3. Wait for 50% of SLA completion
 * 4. Send notification at 50%
 * 5. Wait for 100% of SLA completion
 * 6. Check if SLA was completed or breached
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testSlaTaskTriggerAdvanced = Flow(
    {
        $id: Now.ID['test_sla_task_trigger_advanced_flow'],
        name: 'Test SLA Task Trigger - Advanced',
        description: 'Tests SLA Task trigger with percentage timers and conditional logic',
    },
    wfa.trigger(trigger.application.slaTask, { $id: Now.ID['test_sla_task_trigger_advanced'] }, {}),
    (_params) => {
        // Wait for 25% of SLA
        wfa.action(
            action.core.slaPercentageTimer,
            {
                $id: Now.ID['test_sla_25_percent'],
                annotation: 'Wait for 25% of the SLA',
            },
            {
                percentage: 25,
            }
        )

        // Log at 25%
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_sla_log_25'] },
            {
                log_level: 'warn',
                log_message: `SLA at 25% - Task SLA: ${wfa.dataPill(_params.trigger.task_sla_record, 'records')}, Name: ${wfa.dataPill(_params.trigger.sla_flow_inputs.name, 'string')}, Duration: ${wfa.dataPill(_params.trigger.sla_flow_inputs.duration, 'string')}, Duration Type: ${wfa.dataPill(_params.trigger.sla_flow_inputs.duration_type, 'string')}`,
            }
        )

        // Wait for 50% of SLA
        wfa.action(
            action.core.slaPercentageTimer,
            {
                $id: Now.ID['test_sla_50_percent'],
                annotation: 'Wait for 50% of the SLA',
            },
            {
                percentage: 50,
            }
        )

        // Log at 50%
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_sla_log_50'] },
            {
                log_level: 'warn',
                log_message: `SLA at 50% - Escalation needed`,
            }
        )

        // Wait for 100% of SLA
        const slaComplete = wfa.action(
            action.core.slaPercentageTimer,
            {
                $id: Now.ID['test_sla_100_percent'],
                annotation: 'Wait for 100% of the SLA',
            },
            {
                percentage: 100,
            }
        )

        // Check if SLA was completed successfully
        wfa.flowLogic.if(
            {
                $id: Now.ID['test_sla_if_completed'],
                condition: `${wfa.dataPill(slaComplete.status, 'string')}=completed`,
                annotation: 'Check if SLA is completed',
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['test_sla_log_completed'],
                        annotation: 'Log SLA completion',
                    },
                    {
                        log_level: 'info',
                        log_message: 'SLA task completed successfully',
                    }
                )
            }
        )

        // Check if SLA was breached
        wfa.flowLogic.elseIf(
            {
                $id: Now.ID['test_sla_if_breached'],
                condition: `${wfa.dataPill(slaComplete.status, 'string')}=cancelled`,
                annotation: 'Check if SLA is breached',
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['test_sla_log_cancelled'],
                        annotation: 'Log SLA cancellation',
                    },
                    {
                        log_level: 'error',
                        log_message: 'SLA task cancelled',
                    }
                )
            }
        )
    }
)
